ddl:
CREATE TABLE Customer (
    Address VARCHAR(255),
    Contact_Number VARCHAR(255),
    Customer_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255)
);

CREATE TABLE Raw_Material (
    Raw_Material_ID INTEGER PRIMARY KEY,
    Raw_Material_Name VARCHAR(255),
    Specification VARCHAR(255)
);

CREATE TABLE Financial_Record (
    Amount INTEGER,
    Date DATETIME,
    Status VARCHAR(255),
    Transaction_ID INTEGER PRIMARY KEY,
    Transaction_Type VARCHAR(255)
);

CREATE TABLE Supplier (
    Contact_Information VARCHAR(255),
    Supplier_ID INTEGER PRIMARY KEY,
    Supplier_Name VARCHAR(255)
);

CREATE TABLE Pizza_Recipe (
    Raw_Material_ID INTEGER,
    Recipe_ID INTEGER PRIMARY KEY,
    Usage_Amount INTEGER
);

CREATE TABLE Sales_Order (
    Customer_ID INTEGER NOT NULL,
    Expected_Delivery_Date DATETIME,
    Order_ID INTEGER PRIMARY KEY,
    Order_Status VARCHAR(255),
    FOREIGN KEY (Customer_ID) REFERENCES Customer(Customer_ID)
);

CREATE TABLE Purchase_Order (
    Order_Quantity INTEGER,
    Order_Status VARCHAR(255),
    Purchase_Order_ID INTEGER PRIMARY KEY,
    Raw_Material_ID INTEGER NOT NULL,
    Supplied_Quantity INTEGER,
    Supplier_ID INTEGER NOT NULL,
    FOREIGN KEY (Raw_Material_ID) REFERENCES Raw_Material(Raw_Material_ID),
    FOREIGN KEY (Supplier_ID) REFERENCES Supplier(Supplier_ID)
);

CREATE TABLE Product (
    Product_ID INTEGER PRIMARY KEY,
    Product_Name VARCHAR(255),
    Recipe_ID INTEGER NOT NULL,
    FOREIGN KEY (Recipe_ID) REFERENCES Pizza_Recipe(Recipe_ID)
);

CREATE TABLE Production_Plan (
    Order_ID INTEGER NOT NULL,
    Production_Plan_ID INTEGER PRIMARY KEY,
    Production_Status VARCHAR(255),
    FOREIGN KEY (Order_ID) REFERENCES Sales_Order(Order_ID)
);

CREATE TABLE Delivery_Record (
    Delivery_Location VARCHAR(255),
    Delivery_Record_ID INTEGER PRIMARY KEY,
    Delivery_Time DATETIME,
    Order_ID INTEGER NOT NULL,
    Status VARCHAR(255),
    FOREIGN KEY (Order_ID) REFERENCES Sales_Order(Order_ID)
);

CREATE TABLE Inventory_Management (
    Inventory_ID INTEGER PRIMARY KEY,
    Product_ID INTEGER NOT NULL,
    Quantity INTEGER,
    Status VARCHAR(255),
    FOREIGN KEY (Product_ID) REFERENCES Product(Product_ID)
);
